function validate([matrix, target]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 100) return 'matrix needs 1 to 100 rows.';
  const cols = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (cols < 1 || cols > 100) return 'matrix needs 1 to 100 columns.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each cell is an integer between -1000 and 1000.';
  }
  if (!Number.isInteger(target) || target < -1e8 || target > 1e8) return 'target is an integer between -10^8 and 10^8.';
  return null;
}

