function numSubmatrixSumTarget(matrix, target) {
  const m = matrix.length, n = matrix[0].length;
  // area[i][j] is the sum of the block with corners (0, 0) and (i - 1, j - 1).
  const area = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      area[i][j] = matrix[i - 1][j - 1] + area[i - 1][j] + area[i][j - 1] - area[i - 1][j - 1];
  let total = 0;
  for (let x1 = 0; x1 < m; x1++)
    for (let x2 = x1; x2 < m; x2++)
      for (let y1 = 0; y1 < n; y1++)
        for (let y2 = y1; y2 < n; y2++)
          if (area[x2 + 1][y2 + 1] - area[x1][y2 + 1] - area[x2 + 1][y1] + area[x1][y1] === target) total++;
  return total;
}

