function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 50 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 5);
  const cols = large ? 50 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 5);
  const span = large ? (rand() < 0.5 ? 2 : 1000) : (rand() < 0.5 ? 1 : 3);
  const matrix = Array.from({ length: rows }, () => Array.from({ length: cols }, () => Math.floor(rand() * (2 * span + 1)) - span));
  if (rand() < 0.3) return [matrix, Math.floor(rand() * 5) - 2];
  // Otherwise aim at the sum of a random block so the count is usually positive.
  const x1 = Math.floor(rand() * rows), x2 = x1 + Math.floor(rand() * (rows - x1));
  const y1 = Math.floor(rand() * cols), y2 = y1 + Math.floor(rand() * (cols - y1));
  let target = 0;
  for (let x = x1; x <= x2; x++) for (let y = y1; y <= y2; y++) target += matrix[x][y];
  return [matrix, target];
}
